        LivingEntity attacker = this.mob.getLastHurtByMob();
        if (this.mob instanceof IOwned ownedMob && attacker instanceof IOwned ownedAttacker) {
            if (MobUtil.ownerStack(ownedMob, ownedAttacker)) {
