default LivingEntity getMasterOwner() {
        LivingEntity current = this.getTrueOwner();
        Set<UUID> visited = new HashSet<>();

        while (current != null) {
            UUID currentId = current.getUUID();
            if (!visited.add(currentId)) {
                break;
            }

            if (current instanceof IOwned owned && owned.getTrueOwner() != null) {
                current = owned.getTrueOwner();
            } else if (current instanceof OwnableEntity ownable && ownable.getOwner() != null) {
                current = ownable.getOwner();
            } else {
                break;
            }
        }

        return current != null ? current : this.getTrueOwner();
    }

default void checkHostility() {
        if (this instanceof Entity entity) {
            if (!entity.level.isClientSide) {
                if (this.getTrueOwner() instanceof Enemy) {
                    this.setHostile(true);
                }
                if (this.getTrueOwner() instanceof IOwned owned) {
                    if (owned.isHostile()) {
                        this.setHostile(true);
                    }
                }
                if (this instanceof Enemy) {
                    this.setHostile(true);
                }
            }
        }
    }

default void ownedTick(){
        if (this instanceof Mob mobThis) {
            if (!mobThis.level.isClientSide) {
                if (this.getTrueOwner() instanceof IOwned owned) {
                    try {
                        if (owned.getHasSummonCheck() <= 0) {
                            owned.setHasSummonCheck(2);
                        }
                    } catch (NullPointerException ignored) {
                    }
                    if (this.getTrueOwner().isRemoved() || this.getTrueOwner().isDeadOrDying() || !this.getTrueOwner().isAlive()) {
                        if (owned.getTrueOwner() != null) {
                            this.setTrueOwner(owned.getTrueOwner());
                        } else if (!this.isHostile() && !this.isNatural() && !(owned instanceof Enemy) && !owned.isHostile()) {
                            mobThis.kill();
                        }
                    }
                }
                this.ownerCheck();
                this.targetingTick();
                if (this.getTrueOwner() instanceof Mob mobOwner) {
                    if (mobOwner instanceof Apostle apostle) {
                        if (mobThis.distanceTo(apostle) > 32) {
                            this.teleportTowards(apostle);
                        }
                    }
                    if (mobOwner.getType().is(Tags.EntityTypes.BOSSES) || mobOwner.getType().is(ModTags.EntityTypes.SUMMON_KILL)) {
                        if (mobOwner.isRemoved() || mobOwner.isDeadOrDying()) {
                            mobThis.kill();
                        }
                    }
                }
                this.mobSense();
                if (this.hasLifespan()) {
                    this.setLifespan(this.getLifespan() - 1);
                    if (this.getLifespan() <= 1) {
                        this.lifeSpanDamage();
                    }
                }
                if (this.getHasSummonCheck() > 0) {
                    this.setHasSummonCheck(this.getHasSummonCheck() - 1);
                }
                if (this.getRevivingTime() > 0) {
                    this.reviveTick();
                    this.setRevivingTime(this.getRevivingTime() - 1);
                }
                if (this.getPacifyTick() > 0) {
                    this.pacify();
                    this.setPacifyTick(this.getPacifyTick() - 1);
                }
            }
        }
    }

default void ownerCheck(){
        if (this instanceof Mob mob){
            if (!mob.level.isClientSide) {
                if (this.getTrueOwner() != null) {
                    if (this.getTrueOwner().tickCount < 20) {
                        Entity entity = mob.level.getEntity(this.getOwnerClientId());
                        if (entity instanceof LivingEntity livingEntity) {
                            if (livingEntity != this.getTrueOwner()) {
                                this.setOwnerClientId(this.getTrueOwner().getId());
                            }
                        } else {
                            this.setOwnerClientId(this.getTrueOwner().getId());
                        }
                    }
                }
            }
        }
    }

default void targetingTick() {
        if (this.getPacifyTick() > 0) {
            return;
        }
        if (this instanceof Mob mobThis && !StunnedEvents.isStunned(mobThis)) {
            if (mobThis.getTarget() != null) {
                if (ServantUtil.nullifyTarget(this, mobThis.getTarget()) || mobThis.getTarget().isRemoved() || mobThis.getTarget().isDeadOrDying()) {
                    mobThis.setTarget(null);
                }
            }
            if (this.getTrueOwner() != null) {
                if (this.getTrueOwner() instanceof Mob mobOwner) {
                    if (mobOwner.getTarget() != null && mobThis.getTarget() == null) {
                        mobThis.setTarget(mobOwner.getTarget());
                    }
                }
                for (Mob target : mobThis.level.getEntitiesOfClass(Mob.class, mobThis.getBoundingBox().inflate(mobThis.getAttributeValue(Attributes.FOLLOW_RANGE)), mob1 -> mob1.isAlive() && mobThis != mob1)) {
                    boolean flag = false;
                    if (MainConfig.GoodwillServantGuard.get()) {
                        if (this.isAllyWith(target)) {
                            LivingEntity target2 = null;
                            if (target.getLastHurtByMob() != null && mobThis.getLastHurtByMob() == null) {
                                target2 = target.getLastHurtByMob();
                            } else if (target.getLastHurtMob() != null && mobThis.getLastHurtMob() == null) {
                                target2 = target.getLastHurtMob();
                            }
                            if (target2 != null) {
                                if (!MobUtil.areAllies(mobThis, target2) && mobThis.canAttack(target2, TargetingConditions.DEFAULT)) {
                                    mobThis.setTarget(target2);
                                    mobThis.setLastHurtByMob(target2);
                                    mobThis.setLastHurtMob(target2);
                                }
                            }
                        } else if (target.getTarget() != null) {
                            if (this.isAllyWith(target.getTarget())) {
                                flag = true;
                            }
                        }
                    }
                    if (target instanceof IOwned owned) {
                        if (this.getTrueOwner() != owned.getTrueOwner() && target.getTarget() == this.getTrueOwner()) {
                            flag = true;
                        }
                    }
                    if (flag) {
                        if (mobThis.canAttack(target, TargetingConditions.DEFAULT) && !MobUtil.areAllies(mobThis, target) && !MobUtil.areAllies(this.getTrueOwner(), target)) {
                            mobThis.setTarget(target);
                        }
                    }
                }
            }
        }
    }

default void mobSense(){
        if (this instanceof Mob owned) {
            if (MobsConfig.MobSense.get()) {
                if (owned.isAlive()) {
                    if (owned.getTarget() != null) {
                        if (owned.getTarget() instanceof Mob mob) {
                            if (mob instanceof Animal animal) {
                                animal.setLastHurtByMob(owned);
                            } else if (mob.getTarget() == null) {
                                LivingEntity target = owned;
                                if (mob.getType().is(ModTags.EntityTypes.IGNORE_SERVANTS)) {
                                    if (this.getTrueOwner() != null) {
                                        if (mob.canAttack(this.getTrueOwner()) && EntitySelector.NO_CREATIVE_OR_SPECTATOR.test(mob)) {
                                            target = this.getTrueOwner();
                                        }
                                    }
                                }
                                if (mob instanceof Guardian guardian) {
                                    if (guardian.hasLineOfSight(owned) && guardian.distanceToSqr(owned) > 9.0D) {
                                        mob.setTarget(target);
                                    }
                                } else {
                                    mob.setTarget(target);
                                }
                            }
                            if (!mob.getBrain().isActive(Activity.FIGHT) && !(mob instanceof Warden)) {
                                LivingEntity target = owned;
                                if (mob.getType().is(ModTags.EntityTypes.IGNORE_SERVANTS)) {
                                    if (this.getTrueOwner() != null) {
                                        if (mob.canAttack(this.getTrueOwner()) && EntitySelector.NO_CREATIVE_OR_SPECTATOR.test(mob)) {
                                            target = this.getTrueOwner();
                                        }
                                    }
                                }
                                mob.getBrain().setMemoryWithExpiry(MemoryModuleType.ANGRY_AT, target.getUUID(), 600L);
                                mob.getBrain().setMemoryWithExpiry(MemoryModuleType.ATTACK_TARGET, target, 600L);
                            }
                        }
                    }
                }
            }
        }
    }

default void pacify() {
        if (this instanceof Mob mob) {
            if (mob.getTarget() != null) {
                mob.setTarget(null);
                if (mob.getLastHurtByMob() != null){
                    mob.setLastHurtByMob(null);
                }
                if (mob.getBrain() != null) {
                    mob.getBrain().eraseMemory(MemoryModuleType.ATTACK_TARGET);
                    mob.getBrain().eraseMemory(MemoryModuleType.ANGRY_AT);
                    mob.getBrain().eraseMemory(MemoryModuleType.HURT_BY);
                }
                if (mob instanceof NeutralMob neutralMob) {
                    neutralMob.setPersistentAngerTarget(null);
                    neutralMob.stopBeingAngry();
                }
                mob.setAggressive(false);
            }
        }
    }

default void lifeSpanDamage(){
        if (this instanceof LivingEntity owned) {
            this.setLifespan(20);
            owned.hurt(owned.damageSources().starve(), 1.0F);
        }
    }

default void pacifySurroundingMobs(double range) {
        if (this instanceof LivingEntity owned) {
            for (Mob mob : owned.level.getEntitiesOfClass(Mob.class, owned.getBoundingBox().inflate(range), mob -> !MobUtil.areAllies(mob, owned))) {
                mob.setTarget(null);
                mob.setLastHurtByMob(null);
                Brain<?> brain = mob.getBrain();
                if (brain.hasMemoryValue(MemoryModuleType.ATTACK_TARGET)) {
                    Optional<?> memory = brain.getMemory(MemoryModuleType.ATTACK_TARGET);
                    if (memory.isPresent() && memory.get() == owned) {
                        brain.eraseMemory(MemoryModuleType.ATTACK_TARGET);
                    }
                }
                if (brain.hasMemoryValue(MemoryModuleType.ANGRY_AT)) {
                    Optional<?> memory = brain.getMemory(MemoryModuleType.ANGRY_AT);
                    if (memory.isPresent() && memory.get() == owned.getUUID()) {
                        brain.eraseMemory(MemoryModuleType.ANGRY_AT);
                    }
                }
                if (brain.hasMemoryValue(MemoryModuleType.HURT_BY_ENTITY)) {
                    Optional<?> memory = brain.getMemory(MemoryModuleType.HURT_BY_ENTITY);
                    if (memory.isPresent() && memory.get() == owned) {
                        brain.eraseMemory(MemoryModuleType.HURT_BY_ENTITY);
                    }
                }
            }
        }
    }

default boolean isAllyWith(LivingEntity target) {
        if (this.getTrueOwner() instanceof Player player) {
            return SEHelper.isAlly(player, target);
        } else if (this.getOwnerId() != null && target.level instanceof ServerLevel serverLevel) {
            return SEHelper.isSavedAlly(serverLevel, this.getOwnerId(), target);
        }
        return false;
    }

default boolean isGrudgedTowards(LivingEntity target) {
        if (this.getTrueOwner() instanceof Player player) {
            return SEHelper.isGrudged(player, target);
        } else if (this.getOwnerId() != null && target.level instanceof ServerLevel serverLevel) {
            return SEHelper.isSavedGrudge(serverLevel, this.getOwnerId(), target);
        }
        return false;
    }

default void readOwnedData(CompoundTag compound){
        if (compound.hasUUID("Owner")) {
            this.setOwnerId(compound.getUUID("Owner"));
        }

        if (compound.contains("OwnerClient")){
            this.setOwnerClientId(compound.getInt("OwnerClient"));
        }

        if (compound.contains("isHostile")){
            this.setHostile(compound.getBoolean("isHostile"));
        } else {
            this.checkHostility();
        }

        if (compound.contains("isNatural")){
            this.setNatural(compound.getBoolean("isNatural"));
        }

        if (compound.contains("LifeTicks")) {
            this.setLimitedLife(compound.getInt("LifeTicks"));
        }
        if (compound.contains("RevivePos")){
            this.setRevivePos(NbtUtils.readBlockPos(compound.getCompound("RevivePos")));
            if (compound.contains("ReviveDim")){
                this.setReviveDim(compound.getString("ReviveDim"));
            } else {
                if (this instanceof Entity entity) {
                    this.setReviveDim(entity.level.dimension());
                }
            }
        }
    }

default void saveOwnedData(CompoundTag compound){
        if (this.getOwnerId() != null) {
            compound.putUUID("Owner", this.getOwnerId());
        }
        if (this.getOwnerClientId() > -1) {
            compound.putInt("OwnerClient", this.getOwnerClientId());
        }
        if (this.isHostile()){
            compound.putBoolean("isHostile", this.isHostile());
        }
        if (this.isNatural()){
            compound.putBoolean("isNatural", this.isNatural());
        }
        if (this.isLimitedLife()) {
            compound.putInt("LifeTicks", this.getLifespan());
        }
        if (this.getRevivePos() != null){
            compound.put("RevivePos", NbtUtils.writeBlockPos(this.getRevivePos()));
            compound.putString("ReviveDim", this.getReviveDim());
        }
    }

public static boolean areAllies(@Nullable Entity entity, @Nullable Entity entity1){
        if (entity != null && entity1 != null) {
            if (entity instanceof Player player && entity1 instanceof Player player1) {
                if (entity == entity1) {
                    return true;
                }
                if (SEHelper.isAlly(player, player1) && SEHelper.isAlly(player1, player)) {
                    return true;
                }
                return entity.isAlliedTo(entity1) && entity1.isAlliedTo(entity);
            } else {
                if (entity instanceof Mob mob && entity1 instanceof Mob mob1) {
                    if ((entity instanceof OwnableEntity ownable && entity1 == ownable.getOwner()) || (entity1 instanceof OwnableEntity ownable1 && entity == ownable1.getOwner())) {
                        return mob.getTarget() != mob1 && mob1.getTarget() != mob;
                    }
                }
                return (entity.isAlliedTo(entity1) && entity1.isAlliedTo(entity)) || entity == entity1
                        || (entity instanceof Player player && entity1 instanceof LivingEntity living && SEHelper.isAlly(player, living))
                        || (entity1 instanceof Player player1 && entity instanceof LivingEntity living1 && SEHelper.isAlly(player1, living1));
            }
        } else {
            return false;
        }
    }

public static boolean ownerStack(IOwned owned0, IOwned owned1) {
        LivingEntity master0 = owned0.getMasterOwner();
        LivingEntity master1 = owned1.getMasterOwner();
        return master0 != null && master1 != null && (master0 == master1 || master0.getUUID().equals(master1.getUUID()));
    }

public static boolean isOwnedTargetable(Entity attacker, LivingEntity target){
        LivingEntity owner = null;
        if (MobUtil.getOwner(attacker) != null){
            owner = MobUtil.getOwner(attacker);
        } else if (attacker instanceof Projectile projectile && projectile.getOwner() instanceof LivingEntity livingEntity){
            owner = livingEntity;
        }
        if (owner instanceof Enemy
                || (owner instanceof IOwned owned && owned.isHostile())
                || (attacker instanceof Enemy && !(attacker instanceof IOwned))
                || (attacker instanceof IOwned ownedAttacker && ownedAttacker.isHostile())){
            return target instanceof Player player && EntitySelector.NO_CREATIVE_OR_SPECTATOR.test(player);
        } else if (target instanceof NeutralMob neutralMob) {
            return (owner instanceof Player player && SEHelper.isGrudged(player, target))
                    || (owner instanceof IOwned owned && owned.isGrudgedTowards(target))
                    || (attacker instanceof IOwned owned2 && owned2.isGrudgedTowards(target))
                    || (owner != null && neutralMob.getTarget() == owner) || (neutralMob.getTarget() == attacker);
        } else {
            return (((target instanceof Enemy && !(target instanceof IOwned)) || (target instanceof IOwned ownedTarget && ownedTarget.isHostile()))
                    && !((target.getMobType() == MobType.UNDEAD || target.getType().is(ModTags.EntityTypes.LICH_NEUTRAL)) && LichdomHelper.isLich(owner) && MainConfig.LichUndeadFriends.get())
                    && !(owner != null && ((CuriosFinder.hasNecroSet(owner) && CuriosFinder.validNecroUndead(target)) || (CuriosFinder.neutralNamelessSet(owner) && CuriosFinder.validNamelessUndead(target))) && !MobsConfig.NecroRobeUndead.get())
                    && !(MobUtil.isWitchType(target) && owner != null && CuriosFinder.isWitchFriendly(owner) && !MobsConfig.VariousRobeWitch.get())
                    && !(CuriosFinder.validGeoMob(target) && owner != null && CuriosFinder.neutralGeoSet(owner))
                    && !(CuriosFinder.validFrostMob(target) && owner != null && CuriosFinder.neutralFrostSet(owner))
                    && !(CuriosFinder.validWindMob(target) && owner != null && CuriosFinder.neutralWindSet(owner))
                    && !(CuriosFinder.validStormMob(target) && owner != null && CuriosFinder.neutralStormSet(owner))
                    && !(CuriosFinder.validWildMob(target) && owner != null && CuriosFinder.neutralWildSet(owner))
                    && !(CuriosFinder.validVoidMob(target) && owner != null && CuriosFinder.neutralVoidSet(owner))
                    && !(CuriosFinder.validNetherMob(target) && owner != null && CuriosFinder.neutralNetherSet(owner))
                    && !(target.getMobType() == MobType.ARTHROPOD && owner != null && CuriosFinder.hasWarlockRobe(owner))
                    && !(target instanceof Creeper && target.level.getGameRules().getBoolean(GameRules.RULE_MOBGRIEFING) && MobsConfig.ServantsAttackCreepers.get())
                    && !(target instanceof AbstractPiglin piglin && ((owner != null && piglin.getTarget() != owner) || piglin.getTarget() != attacker))
                    && !(target instanceof IOwned ownedTarget && (owner != null && ownedTarget.getTrueOwner() == owner))
                    || (owner instanceof Player player && (SEHelper.isGrudged(player, target)))
                    || (owner instanceof IOwned owned && owned.isGrudgedTowards(target))
                    || (attacker instanceof IOwned owned2 && owned2.isGrudgedTowards(target)));
        }
    }

public static boolean nullifyTarget(IOwned owned, LivingEntity target) {
        boolean shouldClearTarget = false;
        if (owned instanceof Mob mobThis) {
            if (owned.getMasterOwner() instanceof Player){
                if (mobThis.level.getServer() != null) {
                    if (!mobThis.level.getServer().isPvpAllowed()) {
                        if (target instanceof Player || (target instanceof IOwned owned1 && owned1.getMasterOwner() instanceof Player)) {
                            shouldClearTarget = true;
                        }
                    }
                }
            }
            if (!mobThis.hasEffect(GoetyEffects.WILD_RAGE.get())) {
                if (target instanceof IOwned ownedTarget) {
                    shouldClearTarget = owned.getTrueOwner() != null && ownedTarget.getTrueOwner() == owned.getTrueOwner();
                    if (ownedTarget.getTrueOwner() == owned) {
                        shouldClearTarget = true;
                    }
                    if (MobUtil.ownerStack(owned, ownedTarget)) {
                        shouldClearTarget = true;
                    }
                    if (!shouldClearTarget && owned.isAllyWith(target)) {
                        shouldClearTarget = true;
                    }
                    if (!shouldClearTarget
                            && owned.getTrueOwner() == null
                            && ownedTarget.getTrueOwner() == null
                            && owned.getOwnerId() != null
                            && owned.getOwnerId().equals(ownedTarget.getOwnerId())) {
                        shouldClearTarget = true;
                    }
                    if (!shouldClearTarget
                            && owned.getOwnerId() != null
                            && ownedTarget.getOwnerId() != null
                            && mobThis.level instanceof ServerLevel serverLevel
                            && SEHelper.isSavedAlly(serverLevel, owned.getOwnerId(),
                            target)) {
                        shouldClearTarget = true;
                    }
                } else if (target != null) {
                    if (owned.isAllyWith(target) || (owned.getMasterOwner() != null && target == owned.getMasterOwner()) || target.isRemoved() || target.isDeadOrDying()) {
                        shouldClearTarget = true;
                    }
                }
            }
        }
        return shouldClearTarget;
    }

