        if (this.navigation.isDone()) {
            return false;
        } else if (this.summonedEntity.getTarget() != null){
            return false;
        } else {
            return !(this.summonedEntity.distanceToSqr(this.owner) <= (double)(Mth.square(this.stopDistance)));
        }
