@Override
    public void performRangedAttack(LivingEntity target, float velocity) {
        if (target.distanceTo(this) < 6.0F && this.coolDown <= 0 && this.level.getBlockState(this.blockPosition().above(2)).isAir() && !(this.getTarget() instanceof Raider)) {
            this.totalCool = Mth.nextInt(this.random, 6, 10);
            for (int i = 0; i < this.totalCool; ++i) {
                MobUtil.throwSnapFungus(this, level);
            }
            this.coolDown = MathHelper.secondsToTicks(this.totalCool);
            if (!this.isSilent()) {
                this.level.playSound((Player) null, this.getX(), this.getY(), this.getZ(), ModSounds.BLAST_FUNGUS_THROW.get(), this.getSoundSource(), 2.0F, 0.8F + this.random.nextFloat() * 0.4F);
            }
        } else {
            if (this.level instanceof ServerLevel) {
                if (this.isAlliedTarget(target) && this.getTarget() != target) {
                    if (!this.isSilent()) {
                        this.level.playSound((Player) null, this.getX(), this.getY(), this.getZ(), ModSounds.BLAST_FUNGUS_THROW.get(), this.getSoundSource(), 2.0F, 0.8F + this.random.nextFloat() * 0.4F);
                    }
                    Vec3 vec3 = target.getDeltaMovement();
                    double d0 = target.getX() + vec3.x - this.getX();
                    double d1 = target.getEyeY() - (double)1.1F - this.getY();
                    double d2 = target.getZ() + vec3.z - this.getZ();
                    double d3 = Math.sqrt(d0 * d0 + d2 * d2);
                    BerserkFungus berserkFungus = new BerserkFungus(this, this.level);
                    berserkFungus.setXRot(berserkFungus.getXRot() - 20.0F);
                    berserkFungus.shoot(d0, d1 + d3 * 0.2D, d2, 0.75F, 8.0F);
                    this.level.addFreshEntity(berserkFungus);
                } else {
                    Wartling wartling = new Wartling(ModEntityType.WARTLING.get(), this.level);
                    wartling.setTarget(target);
                    if (this.isInFluidType()){
                        wartling.setPos(this.getX(), this.getY(0.5F), this.getZ());
                        wartling.setXRot(this.getXRot());
                        wartling.setYRot(this.getYRot());
                        double d0 = target.getX() - wartling.getX();
                        double d1 = target.getY(0.3333333333333333D) - wartling.getY();
                        double d2 = target.getZ() - wartling.getZ();
                        double d3 = Mth.sqrt((float) (d0 * d0 + d2 * d2));
                        MobUtil.shoot(wartling, d0, d1 + d3 * (double)0.2F, d2, 1.6F, 1.0F);
                    } else {
                        wartling.moveTo(this.blockPosition(), this.getYRot(), this.getXRot());
                    }
                    this.summonWartlings(wartling);
                }
            }
        }
    }

private void summonWartlings(Wartling wartling){
        if (this.level instanceof ServerLevel serverLevel) {
            wartling.setTrueOwner(this);
            wartling.setLimitedLife(MathHelper.secondsToTicks(9));
            this.getActiveEffects().stream().filter(mobEffect -> mobEffect.getEffect().getCategory() == MobEffectCategory.HARMFUL && !mobEffect.getEffect().getCurativeItems().isEmpty()).findFirst().ifPresent(effect -> {
                wartling.setStoredEffect(effect);
                this.removeEffect(effect.getEffect());
            });
            wartling.finalizeSpawn(serverLevel, serverLevel.getCurrentDifficultyAt(this.blockPosition()), MobSpawnType.MOB_SUMMONED, null, null);
            this.level.addFreshEntity(wartling);
        }
    }

public InteractionResult mobInteract(Player pPlayer, InteractionHand pHand) {
        ItemStack itemstack = pPlayer.getItemInHand(pHand);
        Item item = itemstack.getItem();
        boolean isOwner = this.getTrueOwner() != null && pPlayer == this.getTrueOwner();
        boolean isAlly = ((this.getTrueOwner() != null && MobUtil.areAllies(this.getTrueOwner(), pPlayer)) || this.getTrueOwner() == null) && CuriosFinder.isWitchFriendly(pPlayer);
        if (this.getMainHandItem().isEmpty() && pHand == InteractionHand.MAIN_HAND && itemstack.is(ModTags.Items.WITCH_CURRENCY)) {
            if (isOwner || isAlly) {
                if (!this.isAggressive()) {
                    this.playSound(this.getCelebrateSound());
                    ItemStack itemstack1;
                    if (pPlayer.isCreative()) {
                        itemstack1 = itemstack;
                    } else {
                        itemstack1 = itemstack.split(1);
                    }
                    this.setItemSlot(EquipmentSlot.MAINHAND, itemstack1);
                    this.setTrader(pPlayer);
                    return InteractionResult.SUCCESS;
                }
            }
        }
        if (isOwner) {
            return ServantUtil.equipServantArmor(pPlayer, this, itemstack, super.mobInteract(pPlayer, pHand));
        }
        return super.mobInteract(pPlayer, pHand);
    }

public void aiStep() {
        AttributeInstance attributeinstance = this.getAttribute(Attributes.MOVEMENT_SPEED);
        if (!this.level.isClientSide && this.isAlive()) {
            --this.cooldown;
            if (this.cooldown <= 0 && this.getRandom().nextBoolean()) {
                this.findTarget();
                this.cooldown = 200;
            }
            if (this.getShootTarget() == null) {
                if (this.getTarget() != null && this.getTarget().isAlive()) {
                    this.setShootTarget(this.getTarget());
                }
            }

            if (this.isDrinkingPotion()) {
                if (this.usingTime-- <= 0) {
                    this.setUsingItem(false);
                    ItemStack itemstack = this.getMainHandItem();
                    this.setItemSlot(EquipmentSlot.MAINHAND, ItemStack.EMPTY);
                    if (itemstack.is(Items.POTION)) {
                        List<MobEffectInstance> list = PotionUtils.getMobEffects(itemstack);
                        if (list != null) {
                            for(MobEffectInstance mobeffectinstance : list) {
                                this.addEffect(new MobEffectInstance(mobeffectinstance));
                            }
                        }
                    }

                    if (attributeinstance != null) {
                        attributeinstance.removeModifier(SPEED_MODIFIER_DRINKING);
                    }
                }
            } else {
                Potion potion = null;
                if (this.random.nextFloat() < 0.15F && this.isEyeInFluidType(ForgeMod.WATER_TYPE.get()) && !this.hasEffect(MobEffects.WATER_BREATHING)) {
                    potion = Potions.WATER_BREATHING;
                } else if (this.random.nextFloat() < 0.15F && (this.isOnFire() || this.getLastDamageSource() != null && this.getLastDamageSource().is(DamageTypeTags.IS_FIRE)) && !this.hasEffect(MobEffects.FIRE_RESISTANCE)) {
                    potion = Potions.FIRE_RESISTANCE;
                } else if (this.random.nextFloat() < 0.05F && this.getHealth() < this.getMaxHealth()) {
                    potion = Potions.HEALING;
                } else if (this.random.nextFloat() < 0.5F && this.getTarget() != null && !this.hasEffect(MobEffects.MOVEMENT_SPEED) && this.getTarget().distanceToSqr(this) > 121.0D) {
                    potion = Potions.SWIFTNESS;
                }

                if (potion != null) {
                    this.setItemSlot(EquipmentSlot.MAINHAND, PotionUtils.setPotion(new ItemStack(Items.POTION), potion));
                    this.usingTime = this.getMainHandItem().getUseDuration();
                    this.setUsingItem(true);
                    if (!this.isSilent()) {
                        this.level().playSound((Player)null, this.getX(), this.getY(), this.getZ(), SoundEvents.WITCH_DRINK, this.getSoundSource(), 1.0F, 0.8F + this.random.nextFloat() * 0.4F);
                    }

                    if (attributeinstance != null) {
                        attributeinstance.removeModifier(SPEED_MODIFIER_DRINKING);
                        attributeinstance.addTransientModifier(SPEED_MODIFIER_DRINKING);
                    }
                }
            }

            if (this.random.nextFloat() < 7.5E-4F) {
                this.level().broadcastEntityEvent(this, (byte)15);
            }
        }

        super.aiStep();
    }

public boolean isAlliedTarget(Entity target) {
        if (this.getTrueOwner() != null) {
            return (target == this.getTrueOwner() || MobUtil.getOwner(target) == this.getTrueOwner() || (MobUtil.areAllies(this.getTrueOwner(), target) && MobUtil.notTargetingAlly(target, this)));
        } else {
            return MobUtil.areAllies(this, target);
        }
    }

protected void findTarget() {
        this.shootTarget = this.level.getNearestEntity(this.level.getEntitiesOfClass(LivingEntity.class, this.getTargetSearchArea(this.getAttributeValue(Attributes.FOLLOW_RANGE)), (p_148152_) -> {
            return true;
        }), TargetingConditions.forNonCombat().range(this.getAttributeValue(Attributes.FOLLOW_RANGE))
                .selector(livingEntity -> this.isAlliedTarget(livingEntity) && !(livingEntity instanceof Minion) && livingEntity.getHealth() < livingEntity.getMaxHealth()), this, this.getX(), this.getEyeY(), this.getZ());
    }

public void performRangedAttack(LivingEntity target, float velocity) {
        if (!this.isDrinkingPotion()) {
            Vec3 vec3 = target.getDeltaMovement();
            double d0 = target.getX() + vec3.x - this.getX();
            double d1 = target.getEyeY() - (double)1.1F - this.getY();
            double d2 = target.getZ() + vec3.z - this.getZ();
            double d3 = Math.sqrt(d0 * d0 + d2 * d2);
            Potion potion = Potions.HARMING;
            if (target.isInvertedHealAndHarm()) {
                potion = Potions.HEALING;
            }
            if (this.isAlliedTarget(target) && this.getTarget() != target) {
                if (target.isInvertedHealAndHarm()) {
                    potion = Potions.HARMING;
                } else {
                    if (target.getHealth() <= 4.0F) {
                        potion = Potions.HEALING;
                    } else {
                        potion = Potions.REGENERATION;
                    }
                }

                this.setShootTarget(null);
            } else if (d3 >= 8.0D && !target.hasEffect(MobEffects.MOVEMENT_SLOWDOWN)) {
                potion = Potions.SLOWNESS;
            } else if (target.getHealth() >= 8.0F && target.canBeAffected(new MobEffectInstance(MobEffects.POISON)) && !target.hasEffect(MobEffects.POISON)) {
                potion = Potions.POISON;
            } else if (d3 <= 3.0D && !target.hasEffect(MobEffects.WEAKNESS) && this.random.nextFloat() < 0.25F) {
                potion = Potions.WEAKNESS;
            }

            ThrownPotion thrownpotion = new ThrownPotion(this.level, this);
            thrownpotion.setItem(PotionUtils.setPotion(new ItemStack(Items.SPLASH_POTION), potion));
            thrownpotion.setXRot(thrownpotion.getXRot() - -20.0F);
            thrownpotion.shoot(d0, d1 + d3 * 0.2D, d2, 0.75F, 8.0F);
            if (!this.isSilent()) {
                this.level.playSound((Player)null, this.getX(), this.getY(), this.getZ(), SoundEvents.WITCH_THROW, this.getSoundSource(), 1.0F, 0.8F + this.random.nextFloat() * 0.4F);
            }

            this.level.addFreshEntity(thrownpotion);
        }
    }

@Override
    public boolean doHurtTarget(Entity entityIn) {
        if (this.isMega()){
            if (entityIn instanceof LivingEntity livingEntity){
                if (this.getStoredEffect() != null) {
                    if (!this.getStoredEffect().getEffect().isBeneficial()) {
                        livingEntity.addEffect(this.getStoredEffect());
                    }
                } else if (!livingEntity.getActiveEffects().isEmpty()){
                    livingEntity.getActiveEffects().stream().filter(mobEffect -> mobEffect.getEffect().isBeneficial() && !mobEffect.getEffect().getCurativeItems().isEmpty()).findFirst().ifPresent(effect -> {
                        this.setStoredEffect(effect);
                        livingEntity.removeEffect(effect.getEffect());
                        this.playSound(ModSounds.SPIDER_BITE.get());
                    });
                }
            }
        }
        return super.doHurtTarget(entityIn);
    }

@Override
    public void die(DamageSource pCause) {
        super.die(pCause);
        if (!this.level.isClientSide) {
            if (this.getStoredEffect() != null) {
                AreaEffectCloud areaEffectCloud = new AreaEffectCloud(this.level, this.getX(), this.getY(), this.getZ());
                areaEffectCloud.setRadius(1.0F);
                areaEffectCloud.setWaitTime(0);
                areaEffectCloud.setDuration(MathHelper.secondsToTicks(2));
                areaEffectCloud.addEffect(this.getStoredEffect());
                this.level.addFreshEntity(areaEffectCloud);
            }
        }
    }

public void lifeSpanDamage(){
        if (this.getTrueOwner() != null
                && this.getTrueOwner().isAlive()
                && !this.getTrueOwner().isDeadOrDying()
                && (this.getStoredEffect() == null || this.getStoredEffect().getEffect().isBeneficial())){
            this.getNavigation().moveTo(this.getTrueOwner(), 1.25F);
            this.setTarget(null);
            ++this.searchTime;
            if (this.getBoundingBox().intersects(this.getTrueOwner().getBoundingBox())){
                this.getTrueOwner().heal(this.getHealth());
                for (MobEffectInstance mobEffectInstance : this.getActiveEffects()){
                    if (mobEffectInstance.getEffect().isBeneficial()){
                        this.getTrueOwner().addEffect(mobEffectInstance);
                    }
                }
                if (this.getStoredEffect() != null && this.getStoredEffect().getEffect().isBeneficial()){
                    this.getTrueOwner().addEffect(this.getStoredEffect());
                }
                this.playSound(SoundEvents.SCULK_BLOCK_SPREAD, 1.0F, 1.0F);
                if (!this.level.isClientSide) {
                    this.level.broadcastEntityEvent(this, (byte) 15);
                }
                this.discard();
            } else if (this.searchTime >= MathHelper.secondsToTicks(5)){
                this.hurt(this.damageSources().starve(), this.getMaxHealth());
            }
        } else {
            this.limitedLifeTicks = 20;
            this.hurt(this.damageSources().starve(), this.getMaxHealth());
        }
    }

public boolean canUse() {
            if (this.mob.getTrueOwner() == null || this.mob.getTrueOwner().isDeadOrDying()) {
                return false;
            } else {
                Vec3 vec3 = DefaultRandomPos.getPosAway(this.mob, 16, 7, this.mob.getTrueOwner().position());
                if (vec3 == null) {
                    return false;
                } else if (this.mob.getTrueOwner().distanceToSqr(vec3.x, vec3.y, vec3.z) < this.mob.getTrueOwner().distanceToSqr(this.mob)) {
                    return false;
                } else {
                    this.path = this.pathNav.createPath(vec3.x, vec3.y, vec3.z, 0);
                    return this.path != null
                            && this.mob.getStoredEffect() != null
                            && this.mob.getStoredEffect().getEffect().getCategory() != MobEffectCategory.BENEFICIAL
                            && this.mob.getTarget() == null;
                }
            }
        }

public boolean canContinueToUse() {
            return !this.pathNav.isDone() && this.mob.getTrueOwner() != null && this.mob.getTrueOwner().isAlive();
        }

public void tick() {
            if (this.mob.getTrueOwner() != null) {
                if (this.mob.distanceToSqr(this.mob.getTrueOwner()) < 49.0D) {
                    this.mob.getNavigation().setSpeedModifier(this.sprintSpeedModifier);
                } else {
                    this.mob.getNavigation().setSpeedModifier(this.walkSpeedModifier);
                }
            }
        }

@Override
    public void tick() {
        this.witch.setTarget(null);
        LivingEntity trader = this.witch.getTrader();
        if (--this.progress > 0) {
            this.witch.getNavigation().stop();
            if (trader != null && this.witch.distanceTo(trader) <= 16.0F) {
                this.witch.getLookControl().setLookAt(trader);
            }
        }
        if (this.progress <= 0) {
            Vec3 vec3 = trader != null ? trader.position() : this.witch.position();
            if (!this.witch.level.isClientSide) {
                if (this.witch.level.getServer() != null) {
                    float luck = 0.0F;
                    if (this.witch.getMainHandItem().is(ModTags.Items.WITCH_BETTER_CURRENCY)){
                        luck = 1.0F;
                    }
                    LootTable loottable = this.witch.level.getServer().getLootData().getLootTable(ModLootTables.WITCH_BARTER);
                    if (this.witch instanceof WarlockServant){
                        loottable = this.witch.level.getServer().getLootData().getLootTable(ModLootTables.WARLOCK_BARTER);
                    } else if (this.witch instanceof HereticServant){
                        loottable = this.witch.level.getServer().getLootData().getLootTable(ModLootTables.HERETIC_BARTER);
                    } else if (this.witch instanceof ReprobateServant){
                        loottable = this.witch.level.getServer().getLootData().getLootTable(ModLootTables.REPROBATE_BARTER);
                    }
                    List<ItemStack> list = loottable.getRandomItems((new LootParams.Builder((ServerLevel) this.witch.level)).withParameter(LootContextParams.THIS_ENTITY, this.witch).withParameter(LootContextParams.ORIGIN, this.witch.position()).withLuck(luck).create(LootContextParamSets.GIFT));
                    for(ItemStack itemstack : list) {
                        BehaviorUtils.throwItem(this.witch, itemstack, vec3.add(0.0D, 1.0D, 0.0D));
                    }
                }
            }
            this.clearTrade();
        }

        if (this.witch.hurtTime != 0){
            if (this.witch.getItemInHand(InteractionHand.MAIN_HAND).is(ModTags.Items.WITCH_CURRENCY)) {
                this.witch.spawnAtLocation(this.witch.getItemInHand(InteractionHand.MAIN_HAND));
                this.clearTrade();
            }
        }
    }

@Nullable
    public static LivingEntity getOwner(Entity owned) {
        if (owned == null) {
            return null;
        }
        if (owned instanceof IOwned owned1) {
            return owned1.getTrueOwner();
        } else if (owned instanceof OwnableEntity ownable) {
            return ownable.getOwner();
        } else if (owned instanceof Projectile projectile && projectile.getOwner() instanceof LivingEntity living) {
            if (living instanceof IOwned owned1) {
                return owned1.getTrueOwner();
            } else if (living instanceof OwnableEntity ownable) {
                return ownable.getOwner();
            } else {
                return living;
            }
        }
        return null;
    }

public static boolean notTargetingAlly(Entity attacker, Entity defender) {
        if (getTarget(attacker) == defender) {
            return false;
        } else if (getTarget(attacker) == getOwner(defender)) {
            return false;
        } else return !areAllies(defender, getTarget(attacker));
    }
